content:
:root {
  --bg-color: #f8fafc;
  --card-bg: #ffffff;
  --text-primary: #1e293b;
  --text-secondary: #64748b;
  --accent-color: #3b82f6;
  --border-color: #e2e8f0;
  --shadow-sm: 0 1px 3px 0 rgba(0, 0, 0, 0.1), 0 1px 2px -1px rgba(0, 0, 0, 0.1);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --radius: 12px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-primary);
  line-height: 1.5;
}

.dashboard-app {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px;
}

.header {
  margin-bottom: 24px;
}

.title {
  font-size: 24px;
  font-weight: 700;
  color: var(--text-primary);
}

.cards-container {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 20px;
  margin-bottom: 32px;
}

.stat-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 8px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.stat-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.card-title {
  font-size: 14px;
  font-weight: 600;
  color: var(--text-secondary);
}

.card-value {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-primary);
}

.card-sub {
  font-size: 12px;
  color: var(--text-secondary);
}

.chart-section {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.chart-card {
  background-color: var(--card-bg);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 24px;
  box-shadow: var(--shadow-sm);
}

.chart-title {
  font-size: 18px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 16px;
}

@media (max-width: 768px) {
  .dashboard-app {
    padding: 16px 12px;
  }

  .card-value {
    font-size: 24px;
  }
}

export interface MonthlyData {
  month: string;
  sales: number;
  customers: number;
  averagePrice: number;
}

export interface DashboardProps {
  data: MonthlyData[];
}

export interface StatCardProps {
  title: string;
  value: string;
  subText: string;
  iconType: string;
}

import { StatCardProps } from '../types';

export default function StatCard({ title, value, subText }: StatCardProps) {
  return (
    <div className="stat-card">
      <div className="card-title">{title}</div>
      <div className="card-value">{value}</div>
      <div className="card-sub">{subText}</div>
    </div>
  );
}

import StatCard from './components/StatCard';
import ChartSection from './components/ChartSection';
import { MonthlyData } from './types';

const sampleData: MonthlyData[] = [
  { month: '1月', sales: 1200000, customers: 400, averagePrice: 3000 },
  { month: '2月', sales: 980000, customers: 350, averagePrice: 2800 },
  { month: '3月', sales: 1500000, customers: 480, averagePrice: 3125 },
  { month: '4月', sales: 1350000, customers: 420, averagePrice: 3214 },
  { month: '5月', sales: 1600000, customers: 500, averagePrice: 3200 },
  { month: '6月', sales: 1450000, customers: 460, averagePrice: 3152 },
  { month: '7月', sales: 1800000, customers: 550, averagePrice: 3272 },
  { month: '8月', sales: 1950000, customers: 600, averagePrice: 3250 },
  { month: '9月', sales: 1400000, customers: 440, averagePrice: 3181 },
  { month: '10月', sales: 1550000, customers: 490, averagePrice: 3163 },
  { month: '11月', sales: 1700000, customers: 530, averagePrice: 3207 },
  { month: '12月', sales: 2200000, customers: 680, averagePrice: 3235 },
];

export default function App() {
  const totalSales = sampleData.reduce((acc, cur) => acc + cur.sales, 0);
  const totalCustomers = sampleData.reduce((acc, cur) => acc + cur.customers, 0);
  const overallAveragePrice = Math.round(totalSales / totalCustomers);

  const formattedSales = totalSales.toLocaleString() + ' 円';
  const formattedCustomers = totalCustomers.toLocaleString() + ' 人';
  const formattedAveragePrice = overallAveragePrice.toLocaleString() + ' 円';

  return (
    <div className="dashboard-app">
      <header className="header">
        <h1 className="title">ビジネスダッシュボード</h1>
      </header>

      <div className="cards-container">
        <StatCard 
          title="年間総売上" 
          value={formattedSales} 
          subText="前年比 +12.5%" 
          iconType="sales" 
        />
        <StatCard 
          title="年間総客数" 
          value={formattedCustomers} 
          subText="前年比 +8.2%" 
          iconType="customers" 
        />
        <StatCard 
          title="全体平均単価" 
          value={formattedAveragePrice} 
          subText="前年比 +3.9%" 
          iconType="price" 
        />
      </div>

      <ChartSection data={sampleData} />
    </div>
  );
}
